package com.univmar.quotation.api; import com.univmar.common.api.*; import com.univmar.quotation.QuotationService; import com.univmar.quotation.api.QuotationDtos.*; import com.univmar.quotation.domain.QuotationStatus; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import java.util.*; import org.springframework.data.domain.Pageable; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/quotations") public class QuotationController {private final QuotationService s;public QuotationController(QuotationService s){this.s=s;}@GetMapping public ApiResponse<PageResult> list(@RequestParam(required=false) QuotationStatus status,@PageableDefault(size=20,sort="createdAt") Pageable p,HttpServletRequest r){return ok(s.list(status,p),r);}@PostMapping public ResponseEntity<ApiResponse<Response>> create(@Valid @RequestBody Input i,HttpServletRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ok(s.create(i),r));}@GetMapping("/{id}") public ApiResponse<Response> detail(@PathVariable UUID id,HttpServletRequest r){return ok(s.detail(id),r);}@PutMapping("/{id}") public ApiResponse<Response> update(@PathVariable UUID id,@Valid @RequestBody Input i,HttpServletRequest r){return ok(s.update(id,i),r);}@PostMapping("/{id}/send") public ApiResponse<Response> send(@PathVariable UUID id,HttpServletRequest r){return ok(s.send(id),r);}@PostMapping("/{id}/reject") public ApiResponse<Response> reject(@PathVariable UUID id,HttpServletRequest r){return ok(s.reject(id),r);}@PostMapping("/{id}/expire") public ApiResponse<Response> expire(@PathVariable UUID id,HttpServletRequest r){return ok(s.expire(id),r);}private<T>ApiResponse<T>ok(T x,HttpServletRequest r){return ApiResponse.of(x,(String)r.getAttribute(RequestIdFilter.REQUEST_ID_ATTRIBUTE));}}
